'use client';

/* eslint-disable @next/next/no-img-element */

import { FormEvent, ReactNode, useEffect, useMemo, useState } from 'react';
import { ConfirmModal, EmptyState, Modal, MoneyInput, PageHeader, RiskBadge, SignaturePad, StatusBadge, Stepper, SummaryCard, Toast } from './components';
import { AppSettings, Client, Installment, Loan, Page, Reference, Role, TeamMember, currency, daysLate, defaultSettings, generateInstallments, initials, loanBalance, payableAmount, riskFor, seedClients, seedLoans, seedTeam, shortDate, uid } from './lib';

function usePersistentState<T>(key: string, initial: T) {
  const [state, setState] = useState<T>(() => {
    if (typeof window === 'undefined') return initial;
    try { return JSON.parse(localStorage.getItem(key) || '') as T; } catch { return initial; }
  });
  useEffect(() => { localStorage.setItem(key, JSON.stringify(state)); }, [key, state]);
  return [state, setState] as const;
}

const navItems: { page: Page; label: string; icon: string; roles: Role[] }[] = [
  { page:'home', label:'Visão geral', icon:'⌂', roles:['admin','staff'] },
  { page:'clients', label:'Clientes', icon:'◇', roles:['admin','staff'] },
  { page:'loans', label:'Empréstimos', icon:'▤', roles:['admin','staff'] },
  { page:'payments', label:'Pagamentos', icon:'✓', roles:['admin','staff'] },
  { page:'dashboard', label:'Dashboard', icon:'⌁', roles:['admin'] },
  { page:'team', label:'Equipe', icon:'♙', roles:['admin'] },
  { page:'settings', label:'Configurações', icon:'⚙', roles:['admin'] },
  { page:'client-home', label:'Minha conta', icon:'⌂', roles:['client'] },
];

type ModalState = { type:'contract'|'renegotiate'|'payment'|'team'|'confirm-payment'|'reject-payment'; loanId?:string; installmentId?:string } | null;

export default function App() {
  const [clients, setClients] = usePersistentState<Client[]>('le-clients', seedClients);
  const [loans, setLoans] = usePersistentState<Loan[]>('le-loans', seedLoans);
  const [team, setTeam] = usePersistentState<TeamMember[]>('le-team', seedTeam);
  const [settings, setSettings] = usePersistentState<AppSettings>('le-settings', defaultSettings);
  const [role, setRole] = usePersistentState<Role>('le-role', 'admin');
  const [clientSession, setClientSession] = usePersistentState('le-client-session', seedClients[0].id);
  const [loggedIn, setLoggedIn] = useState(true);
  const [page, setPage] = useState<Page>(role === 'client' ? 'client-home' : 'home');
  const [selectedClient, setSelectedClient] = useState<string | null>(null);
  const [selectedLoan, setSelectedLoan] = useState<string | null>(null);
  const [prefilledClient, setPrefilledClient] = useState<string | undefined>();
  const [modal, setModal] = useState<ModalState>(null);
  const [toast, setToast] = useState('');
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);

  const notify = (message: string) => setToast(message);
  const navigate = (target: Page, id?: string) => {
    if (target === 'client-detail') setSelectedClient(id || null);
    if (target === 'loan-detail') setSelectedLoan(id || null);
    setPage(target); setMobileMenu(false); window.scrollTo({top:0,behavior:'smooth'});
  };
  const addClient = (client: Client) => { setClients(items => [client, ...items]); setSelectedClient(client.id); setPage('client-detail'); notify('Cliente cadastrado com sucesso.'); };
  const createLoan = (loan: Loan) => { setLoans(items => [loan, ...items]); setSelectedLoan(loan.id); setPage('loan-detail'); notify('Empréstimo e parcelas criados com sucesso.'); };
  const updateInstallment = (loanId: string, installmentId: string, update: Partial<Installment>) => setLoans(items => items.map(loan => loan.id === loanId ? {...loan, installments:loan.installments.map(item => item.id === installmentId ? {...item,...update} : item)} : loan));
  const confirmPayment = (loanId: string, installmentId: string) => {
    const loan = loans.find(item => item.id === loanId); const installment = loan?.installments.find(item => item.id === installmentId);
    updateInstallment(loanId, installmentId, { status:'Pago', paidAmount: installment ? payableAmount(loan!, installment) : 0, paidAt:new Date().toISOString().slice(0,10) });
    notify('Pagamento confirmado e cliente notificado.');
  };
  const rejectPayment = (loanId: string, installmentId: string) => { updateInstallment(loanId, installmentId, { status:'Pendente', receiptName:undefined }); notify('Comprovação recusada. A parcela voltou para pendente.'); };
  const markAsPaid = (loanId: string, installmentId: string, receipt?: string) => { updateInstallment(loanId, installmentId, { status:'Aguardando', receiptName:receipt }); notify('Pagamento enviado para confirmação.'); };
  const addRenegotiation = (loan: Loan) => { setLoans(items => [loan, ...items.map(item => item.id === loan.originalLoanId ? {...item,status:'Renegociado' as const} : item)]); setSelectedLoan(loan.id); setPage('loan-detail'); setModal(null); notify('Renegociação criada e vinculada ao contrato original.'); };

  if (!loggedIn) return <Login clients={clients} onLogin={(newRole, clientId) => { setRole(newRole); if (clientId) setClientSession(clientId); setPage(newRole === 'client' ? 'client-home' : 'home'); setLoggedIn(true); }} />;

  const allowedNav = navItems.filter(item => item.roles.includes(role));
  const pendingCount = loans.flatMap(loan => loan.installments).filter(item => item.status === 'Aguardando' || item.status === 'Atrasado').length;
  const currentClient = clients.find(item => item.id === clientSession) || clients[0];
  const currentTitle = navItems.find(item => item.page === page)?.label || (page.includes('client') ? 'Cliente' : page.includes('loan') ? 'Empréstimo' : 'Lucas EMPRED');

  let view: ReactNode;
  switch (page) {
    case 'clients': view = <ClientsView clients={clients} loans={loans} onOpen={id => navigate('client-detail', id)} onNew={() => navigate('new-client')} />; break;
    case 'new-client': view = <NewClientView onSave={addClient} onCancel={() => navigate('clients')} />; break;
    case 'client-detail': {
      const client = clients.find(item => item.id === selectedClient);
      view = client ? <ClientDetail client={client} loans={loans} onOpenLoan={id => navigate('loan-detail', id)} onNewLoan={() => { setPrefilledClient(client.id); navigate('new-loan'); }} onValidateReference={index => setClients(items => items.map(item => item.id === client.id ? {...item,references:item.references.map((ref,i) => i === index ? {...ref,validated:true} : ref)} : item))} /> : <EmptyState title="Cliente não encontrado" text="Volte à lista e selecione outro cadastro." />;
      break;
    }
    case 'loans': view = <LoansView loans={loans} clients={clients} onOpen={id => navigate('loan-detail', id)} onNew={() => { setPrefilledClient(undefined); navigate('new-loan'); }} />; break;
    case 'new-loan': view = <NewLoanView clients={clients} loans={loans} settings={settings} prefilledClient={prefilledClient} onSave={createLoan} onCancel={() => navigate('loans')} />; break;
    case 'loan-detail': {
      const loan = loans.find(item => item.id === selectedLoan); const client = loan ? clients.find(item => item.id === loan.clientId) : undefined;
      view = loan && client ? <LoanDetail loan={loan} client={client} onContract={() => setModal({type:'contract',loanId:loan.id})} onRenegotiate={() => setModal({type:'renegotiate',loanId:loan.id})} onConfirm={(installmentId) => setModal({type:'confirm-payment',loanId:loan.id,installmentId})} /> : <EmptyState title="Empréstimo não encontrado" text="Volte à carteira e selecione outro contrato." />;
      break;
    }
    case 'payments': view = <PaymentsView loans={loans} clients={clients} onConfirm={(loanId, installmentId) => setModal({type:'confirm-payment',loanId,installmentId})} onReject={(loanId, installmentId) => setModal({type:'reject-payment',loanId,installmentId})} onOpenLoan={id => navigate('loan-detail', id)} />; break;
    case 'dashboard': view = <DashboardView clients={clients} loans={loans} />; break;
    case 'team': view = <TeamView team={team} setTeam={setTeam} onNew={() => setModal({type:'team'})} notify={notify} />; break;
    case 'settings': view = <SettingsView value={settings} onSave={value => { setSettings(value); notify('Configurações salvas.'); }} />; break;
    case 'client-home': view = <ClientHome client={currentClient} loans={loans} settings={settings} onPayment={(loanId, installmentId) => setModal({type:'payment',loanId,installmentId})} />; break;
    default: view = <AdminHome clients={clients} loans={loans} role={role} onNavigate={navigate} onNewLoan={() => navigate('new-loan')} />;
  }

  const modalLoan = modal?.loanId ? loans.find(item => item.id === modal.loanId) : undefined;
  const modalClient = modalLoan ? clients.find(item => item.id === modalLoan.clientId) : undefined;
  const modalInstallment = modalLoan && modal?.installmentId ? modalLoan.installments.find(item => item.id === modal.installmentId) : undefined;

  return <main className="app-shell">
    <aside className={`sidebar ${mobileMenu ? 'open' : ''}`}>
      <button className="brand" onClick={() => navigate(role === 'client' ? 'client-home' : 'home')}><span className="brand-mark">L</span><span>Lucas <b>EMPRED</b></span></button>
      <nav aria-label="Navegação principal">{allowedNav.map(item => <button key={item.page} className={`nav-item ${page === item.page || (item.page === 'clients' && page.includes('client')) || (item.page === 'loans' && page.includes('loan')) ? 'active' : ''}`} onClick={() => navigate(item.page)}><span className="nav-icon">{item.icon}</span>{item.label}{item.page === 'payments' && pendingCount > 0 && <em>{pendingCount}</em>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="profile"><span className="avatar">{role === 'client' ? initials(currentClient.name) : role === 'staff' ? 'CR' : 'LS'}</span><span><b>{role === 'client' ? currentClient.name : role === 'staff' ? 'Camila Rocha' : 'Lucas Silva'}</b><small>{role === 'client' ? 'Cliente' : role === 'staff' ? 'Equipe' : 'Administrador'}</small></span></div></div>
    </aside>
    {mobileMenu && <button className="menu-scrim" aria-label="Fechar menu" onClick={() => setMobileMenu(false)} />}
    <section className="main-area">
      <header className="topbar">
        <div className="mobile-brand"><button className="hamburger" onClick={() => setMobileMenu(true)} aria-label="Abrir menu">☰</button><span className="mini-mark">L</span></div>
        <div className="top-title"><p className="eyebrow">{new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date()).toUpperCase()}</p><h1>{page === 'home' ? `Olá, ${role === 'staff' ? 'Camila' : 'Lucas'}` : currentTitle}</h1></div>
        <div className="top-actions">
          <button className="icon-button notification-button" onClick={() => setNotificationsOpen(value => !value)} aria-label="Notificações">●{pendingCount > 0 && <em>{pendingCount}</em>}</button>
          {role !== 'client' && <button className="primary-button desktop-action" onClick={() => navigate('new-loan')}>＋ Novo empréstimo</button>}
          <button className="top-avatar" onClick={() => setAccountOpen(value => !value)}>{role === 'client' ? initials(currentClient.name) : role === 'staff' ? 'CR' : 'LS'}</button>
        </div>
        {notificationsOpen && <Notifications loans={loans} clients={clients} onClose={() => setNotificationsOpen(false)} onOpen={(loanId) => { setNotificationsOpen(false); navigate('loan-detail',loanId); }} />}
        {accountOpen && <div className="account-menu"><b>{role === 'client' ? currentClient.name : role === 'staff' ? 'Camila Rocha' : 'Lucas Silva'}</b><small>{role === 'client' ? currentClient.cpf : role === 'staff' ? 'Acesso da equipe' : 'Acesso total'}</small><button onClick={() => { setAccountOpen(false); setLoggedIn(false); }}>Trocar perfil / sair</button></div>}
      </header>
      <div className="content">{view}</div>
    </section>
    <nav className="mobile-nav" aria-label="Navegação móvel">{allowedNav.slice(0,4).map(item => <button key={item.page} className={page === item.page ? 'active' : ''} onClick={() => navigate(item.page)}><span>{item.icon}</span>{item.label === 'Visão geral' ? 'Início' : item.label}</button>)}</nav>
    {toast && <Toast message={toast} onDone={() => setToast('')} />}
    {modal?.type === 'contract' && modalLoan && modalClient && <ContractModal loan={modalLoan} client={modalClient} settings={settings} onClose={() => setModal(null)} />}
    {modal?.type === 'renegotiate' && modalLoan && <RenegotiateModal loan={modalLoan} settings={settings} onSave={addRenegotiation} onClose={() => setModal(null)} />}
    {modal?.type === 'payment' && modalLoan && modalInstallment && <PaymentModal loan={modalLoan} installment={modalInstallment} settings={settings} onSave={(receipt) => { markAsPaid(modalLoan.id,modalInstallment.id,receipt); setModal(null); }} onClose={() => setModal(null)} />}
    {modal?.type === 'team' && <TeamModal onSave={member => { setTeam(items => [...items,member]); setModal(null); notify('Membro adicionado à equipe.'); }} onClose={() => setModal(null)} />}
    {modal?.type === 'confirm-payment' && modalLoan && modalInstallment && <ConfirmModal title="Confirmar recebimento?" description={`Confirme o recebimento de ${currency(payableAmount(modalLoan,modalInstallment))}. Esta ação dará baixa na parcela ${modalInstallment.number}.`} confirmLabel="Confirmar pagamento" onConfirm={() => confirmPayment(modalLoan.id,modalInstallment.id)} onClose={() => setModal(null)} />}
    {modal?.type === 'reject-payment' && modalLoan && modalInstallment && <ConfirmModal title="Recusar comprovação?" description="A parcela voltará para o status pendente e o cliente verá que precisa reenviar o comprovante." confirmLabel="Recusar envio" destructive onConfirm={() => rejectPayment(modalLoan.id,modalInstallment.id)} onClose={() => setModal(null)} />}
  </main>;
}

function Login({ clients, onLogin }: { clients: Client[]; onLogin:(role:Role,clientId?:string)=>void }) {
  const [role, setRole] = useState<Role>('admin'); const [clientId,setClientId] = useState(clients[0]?.id || ''); const [password,setPassword] = useState('');
  return <main className="login-page"><section className="login-brand"><div className="login-logo"><span>L</span>Lucas <b>EMPRED</b></div><div><p>Gestão que transmite confiança.</p><h1>Controle cada empréstimo do início ao fim.</h1><span>Clientes, contratos, cobranças semanais e resultados em um só lugar.</span></div><small>Ambiente demonstrativo • dados armazenados neste dispositivo</small></section><section className="login-panel"><form onSubmit={event => {event.preventDefault();onLogin(role,role === 'client' ? clientId : undefined)}}><p className="eyebrow">BEM-VINDO DE VOLTA</p><h2>Acesse sua conta</h2><p className="form-intro">Escolha o perfil para explorar cada área do sistema.</p><div className="role-picker">{(['admin','staff','client'] as Role[]).map(item => <button type="button" className={role === item ? 'active' : ''} onClick={() => setRole(item)} key={item}>{item === 'admin' ? 'Admin' : item === 'staff' ? 'Equipe' : 'Cliente'}</button>)}</div>{role === 'client' ? <label>Cliente<select value={clientId} onChange={event => setClientId(event.target.value)}>{clients.map(client => <option value={client.id} key={client.id}>{client.name}</option>)}</select></label> : <label>E-mail<input type="email" defaultValue={role === 'admin' ? 'admin@lucasempred.com.br' : 'camila@lucasempred.com.br'} /></label>}<label>Senha<div className="password-field"><input type="password" value={password} onChange={event => setPassword(event.target.value)} placeholder="Digite qualquer senha" required /><span>●●</span></div></label><button className="primary-button login-button">Entrar no sistema</button><small className="demo-note">Nesta fase, o acesso é simulado. A autenticação segura será conectada depois.</small></form></section></main>;
}

function AdminHome({ clients, loans, role, onNavigate, onNewLoan }: { clients:Client[]; loans:Loan[]; role:Role; onNavigate:(page:Page,id?:string)=>void; onNewLoan:()=>void }) {
  const all = loans.flatMap(loan => loan.installments.map(item => ({...item,loan})));
  const received = all.filter(item => item.status === 'Pago').reduce((sum,item) => sum + item.paidAmount,0);
  const active = loans.filter(loan => loan.status === 'Ativo').reduce((sum,loan) => sum + loanBalance(loan),0);
  const late = all.filter(item => item.status === 'Atrasado'); const awaiting = all.filter(item => item.status === 'Aguardando');
  const upcoming = all.filter(item => item.status !== 'Pago').sort((a,b) => a.dueDate.localeCompare(b.dueDate)).slice(0,4);
  const chart = [52,66,48,78,65,88];
  return <>
    <section className="welcome-strip"><div><span className="live-dot" />Resumo do dia</div><p>Você tem <b>{upcoming.length} parcelas próximas</b> e <b>{awaiting.length} pagamento(s)</b> aguardando confirmação.</p><button onClick={() => onNavigate('payments')}>Ver pagamentos →</button></section>
    <PageHeader eyebrow="VISÃO GERAL" title={role === 'staff' ? 'Sua operação hoje' : 'Saúde da carteira'} subtitle="Os números mais importantes, atualizados com cada movimentação." action={<button className="primary-button mobile-only" onClick={onNewLoan}>＋ Novo</button>} />
    <section className="summary-grid"><SummaryCard label="Carteira ativa" value={currency(active)} detail={`${loans.filter(item=>item.status==='Ativo').length} contratos ativos`} tone="navy" icon="$"/><SummaryCard label="Total recebido" value={currency(received)} detail="Pagamentos confirmados" tone="green" icon="✓"/><SummaryCard label="Em atraso" value={currency(late.reduce((sum,item)=>sum+payableAmount(item.loan,item),0))} detail={`${late.length} parcelas`} tone="red" icon="!"/><SummaryCard label="A confirmar" value={currency(awaiting.reduce((sum,item)=>sum+item.amount,0))} detail={`${awaiting.length} comprovantes`} tone="gold" icon="↗"/></section>
    <div className="dashboard-grid"><section className="panel cashflow-panel"><div className="panel-head"><div><p className="eyebrow">DESEMPENHO</p><h3>Fluxo de caixa</h3></div><button className="text-button" onClick={() => onNavigate('dashboard')}>Análise completa</button></div><div className="chart-legend"><span><i className="planned"/>Previsto</span><span><i className="received"/>Realizado</span></div><div className="bar-chart">{chart.map((height,index)=><div className="bar-group" key={index}><div className="bars"><span style={{height:`${height}%`}}/><span style={{height:`${Math.max(22,height-(index%2?5:13))}%`}}/></div><small>{['Mar','Abr','Mai','Jun','Jul','Ago'][index]}</small></div>)}</div></section><section className="panel"><div className="panel-head"><div><p className="eyebrow">PRÓXIMOS</p><h3>Vencimentos</h3></div><button className="text-button" onClick={()=>onNavigate('loans')}>Ver todos</button></div><div className="payment-list">{upcoming.map(item=>{const client=clients.find(c=>c.id===item.loan.clientId)!;return <button className="payment-row" key={item.id} onClick={()=>onNavigate('loan-detail',item.loan.id)}><span className="avatar light">{initials(client.name)}</span><span><b>{client.name}</b><small>{shortDate(item.dueDate)} • Parcela {item.number}</small></span><span className="payment-value"><b>{currency(payableAmount(item.loan,item))}</b><StatusBadge status={item.status}/></span></button>})}</div></section></div>
    <section className="quick-actions"><button onClick={()=>onNavigate('new-client')}><span>＋</span><b>Novo cliente</b><small>Cadastre dados e referências</small></button><button onClick={onNewLoan}><span>↗</span><b>Novo empréstimo</b><small>Simule e gere as parcelas</small></button><button onClick={()=>onNavigate('payments')}><span>✓</span><b>Confirmar pagamentos</b><small>Revise comprovantes enviados</small></button></section>
  </>;
}

function ClientsView({ clients, loans, onOpen, onNew }: { clients:Client[]; loans:Loan[]; onOpen:(id:string)=>void; onNew:()=>void }) {
  const [search,setSearch]=useState(''); const filtered=clients.filter(client=>`${client.name} ${client.cpf} ${client.phone}`.toLowerCase().includes(search.toLowerCase()));
  return <><PageHeader eyebrow="CARTEIRA DE CLIENTES" title="Clientes" subtitle={`${clients.length} pessoas cadastradas`} action={<button className="primary-button" onClick={onNew}>＋ Novo cliente</button>}/><div className="toolbar"><label className="search-field"><span>⌕</span><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Buscar por nome, CPF ou telefone"/></label><select aria-label="Filtrar risco"><option>Todos os riscos</option><option>Baixo risco</option><option>Médio risco</option><option>Alto risco</option></select></div><section className="table-card"><div className="data-table client-table"><div className="table-row table-head"><span>Cliente</span><span>Contato</span><span>Score</span><span>Em aberto</span><span></span></div>{filtered.map(client=>{const risk=riskFor(client,loans);const active=loans.filter(loan=>loan.clientId===client.id&&loan.status==='Ativo');return <button className="table-row" key={client.id} onClick={()=>onOpen(client.id)}><span className="person-cell"><i className="avatar light">{initials(client.name)}</i><span><b>{client.name}</b><small>{client.cpf}</small></span></span><span><b>{client.phone}</b><small>{client.address.split('—')[0]}</small></span><RiskBadge level={risk.level} score={risk.score}/><span><b>{currency(active.reduce((sum,loan)=>sum+loanBalance(loan),0))}</b><small>{active.length} contrato(s)</small></span><span className="row-arrow">›</span></button>})}</div>{!filtered.length&&<EmptyState title="Nenhum cliente encontrado" text="Tente outro termo de busca."/>}</section></>;
}

function NewClientView({ onSave, onCancel }: { onSave:(client:Client)=>void; onCancel:()=>void }) {
  const [step,setStep]=useState(0); const [signature,setSignature]=useState(''); const [documents,setDocuments]=useState<string[]>([]); const [form,setForm]=useState({name:'',cpf:'',rg:'',phone:'',address:'',income:0,ref1:'',phone1:'',ref2:'',phone2:''});
  const update=(key:string,value:string|number)=>setForm(state=>({...state,[key]:value}));
  const submit=(event:FormEvent)=>{event.preventDefault();if(step<2){setStep(value=>value+1);return;}const references:Reference[]=[{name:form.ref1,phone:form.phone1,validated:false},{name:form.ref2,phone:form.phone2,validated:false}];onSave({id:uid('cli'),name:form.name,cpf:form.cpf,rg:form.rg,phone:form.phone,address:form.address,income:form.income,references,documents,signature,createdAt:new Date().toISOString().slice(0,10)});};
  return <><PageHeader eyebrow="NOVO CADASTRO" title="Cadastrar cliente" subtitle="Preencha os dados em três etapas. Você poderá editar depois."/><Stepper steps={['Dados pessoais','Documentos','Referências e assinatura']} active={step}/><form className="form-card" onSubmit={submit}>{step===0&&<><div className="form-section-title"><span>1</span><div><h3>Dados pessoais</h3><p>Informações básicas para identificar e contatar o cliente.</p></div></div><div className="form-grid"><label className="span-2">Nome completo<input required value={form.name} onChange={e=>update('name',e.target.value)} placeholder="Nome sem abreviações"/></label><label>CPF<input required value={form.cpf} onChange={e=>update('cpf',e.target.value)} placeholder="000.000.000-00"/></label><label>RG<input required value={form.rg} onChange={e=>update('rg',e.target.value)} placeholder="Documento de identidade"/></label><label>Telefone<input required value={form.phone} onChange={e=>update('phone',e.target.value)} placeholder="(00) 00000-0000"/></label><label>Renda mensal<MoneyInput value={form.income} onChange={value=>update('income',value)} required/></label><label className="span-2">Endereço completo<input required value={form.address} onChange={e=>update('address',e.target.value)} placeholder="Rua, número, bairro e cidade"/></label></div></>}{step===1&&<><div className="form-section-title"><span>2</span><div><h3>Documentos</h3><p>Adicione comprovante de renda e documento com foto.</p></div></div><label className="upload-zone"><input type="file" multiple accept="image/*,.pdf" onChange={event=>setDocuments(Array.from(event.target.files||[]).map(file=>file.name))}/><span>↑</span><b>Toque para selecionar arquivos</b><small>Fotos ou PDF • os arquivos serão conectados ao armazenamento depois</small></label>{documents.length>0&&<div className="file-list">{documents.map(file=><span key={file}>▤ {file}</span>)}</div>}</>}{step===2&&<><div className="form-section-title"><span>3</span><div><h3>Referências e assinatura</h3><p>Cadastre duas referências pessoais e capture a assinatura.</p></div></div><div className="reference-grid"><div><h4>Referência 1</h4><label>Nome<input required value={form.ref1} onChange={e=>update('ref1',e.target.value)}/></label><label>Telefone<input required value={form.phone1} onChange={e=>update('phone1',e.target.value)}/></label></div><div><h4>Referência 2</h4><label>Nome<input required value={form.ref2} onChange={e=>update('ref2',e.target.value)}/></label><label>Telefone<input required value={form.phone2} onChange={e=>update('phone2',e.target.value)}/></label></div></div><label className="standalone-label">Assinatura digital</label><SignaturePad value={signature} onChange={setSignature}/></>}<div className="form-actions"><button type="button" className="secondary-button" onClick={step?()=>setStep(value=>value-1):onCancel}>{step?'Voltar':'Cancelar'}</button><button className="primary-button">{step===2?'Salvar cliente':'Continuar →'}</button></div></form></>;
}

function ClientDetail({ client, loans, onOpenLoan, onNewLoan, onValidateReference }: {client:Client;loans:Loan[];onOpenLoan:(id:string)=>void;onNewLoan:()=>void;onValidateReference:(index:number)=>void}) {
  const clientLoans=loans.filter(loan=>loan.clientId===client.id);const risk=riskFor(client,loans);const paid=clientLoans.flatMap(loan=>loan.installments).filter(item=>item.status==='Pago').length;const late=clientLoans.flatMap(loan=>loan.installments).filter(item=>item.status==='Atrasado').length;
  return <><PageHeader eyebrow="FICHA DO CLIENTE" title={client.name} subtitle={`${client.cpf} • Cliente desde ${shortDate(client.createdAt)}`} action={<button className="primary-button" onClick={onNewLoan}>＋ Novo empréstimo</button>}/><div className="detail-grid"><section className="profile-card panel"><div className="client-hero"><span className="avatar large">{initials(client.name)}</span><div><h3>{client.name}</h3><p>{client.phone}</p></div></div><dl><div><dt>RG</dt><dd>{client.rg}</dd></div><div><dt>Renda declarada</dt><dd>{currency(client.income)}</dd></div><div className="span-2"><dt>Endereço</dt><dd>{client.address}</dd></div></dl></section><section className="risk-card panel"><div className="risk-score"><div className={`score-ring ${risk.level==='Baixo risco'?'low':risk.level==='Médio risco'?'medium':'high'}`} style={{'--score':`${risk.score*3.6}deg`} as React.CSSProperties}><span>{risk.score}<small>/100</small></span></div><div><p className="eyebrow">ANÁLISE AUTOMÁTICA</p><h3>{risk.level}</h3><p>{risk.level==='Baixo risco'?'Perfil recomendado para análise de crédito.':'Revise os fatores antes de aprovar.'}</p></div></div><ul>{risk.reasons.slice(0,3).map(reason=><li key={reason}>✓ {reason}</li>)}</ul></section></div><section className="summary-grid three"><SummaryCard label="Saldo em aberto" value={currency(clientLoans.reduce((sum,loan)=>sum+loanBalance(loan),0))} detail={`${clientLoans.filter(item=>item.status==='Ativo').length} contratos ativos`} /><SummaryCard label="Parcelas pagas" value={String(paid)} detail="Histórico confirmado" tone="green"/><SummaryCard label="Parcelas atrasadas" value={String(late)} detail={late?'Requer atenção':'Tudo em dia'} tone={late?'red':'green'}/></section><div className="detail-grid"><section className="panel"><div className="panel-head"><h3>Empréstimos</h3></div>{clientLoans.length?<div className="compact-list">{clientLoans.map(loan=><button key={loan.id} onClick={()=>onOpenLoan(loan.id)}><span><b>{loan.contractNumber}</b><small>{currency(loan.principal)} • {loan.weeks} semanas</small></span><StatusBadge status={loan.status}/><strong>{currency(loanBalance(loan))}</strong><i>›</i></button>)}</div>:<EmptyState title="Sem empréstimos" text="Este cliente ainda não possui contratos."/>}</section><section className="panel"><div className="panel-head"><h3>Referências pessoais</h3><span className="subtle-count">{client.references.filter(ref=>ref.validated).length}/2 validadas</span></div><div className="reference-list">{client.references.map((ref,index)=><div key={`${ref.name}-${index}`}><span className="avatar light">{initials(ref.name)}</span><span><b>{ref.name}</b><small>{ref.phone}</small></span>{ref.validated?<span className="verified">✓ Validada</span>:<button className="outline-button small" onClick={()=>onValidateReference(index)}>Validar</button>}</div>)}</div><div className="document-list"><h4>Documentos</h4>{client.documents.length?client.documents.map(file=><button key={file}>▤ {file}<span>Visualizar</span></button>):<p>Nenhum documento anexado.</p>}</div></section></div></>;
}

function LoansView({ loans, clients, onOpen, onNew }: {loans:Loan[];clients:Client[];onOpen:(id:string)=>void;onNew:()=>void}) {
  const [search,setSearch]=useState('');const [filter,setFilter]=useState('Todos');const list=loans.filter(loan=>{const client=clients.find(c=>c.id===loan.clientId);return `${client?.name} ${loan.contractNumber}`.toLowerCase().includes(search.toLowerCase())&&(filter==='Todos'||loan.status===filter)});
  return <><PageHeader eyebrow="CARTEIRA" title="Empréstimos" subtitle={`${loans.filter(item=>item.status==='Ativo').length} contratos ativos`} action={<button className="primary-button" onClick={onNew}>＋ Novo empréstimo</button>}/><section className="summary-grid three"><SummaryCard label="Capital emprestado" value={currency(loans.reduce((sum,loan)=>sum+loan.principal,0))}/><SummaryCard label="Saldo da carteira" value={currency(loans.reduce((sum,loan)=>sum+loanBalance(loan),0))} tone="gold"/><SummaryCard label="Juros contratados" value={currency(loans.reduce((sum,loan)=>sum+loan.installments.reduce((s,i)=>s+i.interest,0),0))} tone="green"/></section><div className="toolbar"><label className="search-field"><span>⌕</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar cliente ou contrato"/></label><select value={filter} onChange={e=>setFilter(e.target.value)}><option>Todos</option><option>Ativo</option><option>Quitado</option><option>Renegociado</option></select></div><section className="loan-card-grid">{list.map(loan=>{const client=clients.find(c=>c.id===loan.clientId)!;const paid=loan.installments.filter(i=>i.status==='Pago').length;return <button className="loan-card" key={loan.id} onClick={()=>onOpen(loan.id)}><div className="loan-card-top"><span className="avatar light">{initials(client.name)}</span><span><b>{client.name}</b><small>{loan.contractNumber}</small></span><StatusBadge status={loan.status}/></div><div className="loan-values"><span><small>Emprestado</small><b>{currency(loan.principal)}</b></span><span><small>Saldo</small><b>{currency(loanBalance(loan))}</b></span></div><div className="progress"><span style={{width:`${paid/loan.installments.length*100}%`}}/></div><div className="loan-card-foot"><span>{paid} de {loan.installments.length} parcelas pagas</span><b>{loan.rate}% juros</b></div></button>})}</section>{!list.length&&<EmptyState title="Nenhum empréstimo" text="Ajuste os filtros ou crie um novo contrato." action={<button className="primary-button" onClick={onNew}>Novo empréstimo</button>}/>}</>;
}

function NewLoanView({ clients, loans, settings, prefilledClient, onSave, onCancel }: {clients:Client[];loans:Loan[];settings:AppSettings;prefilledClient?:string;onSave:(loan:Loan)=>void;onCancel:()=>void}) {
  const [step,setStep]=useState(0);const [clientId,setClientId]=useState(prefilledClient||clients[0]?.id||'');const [principal,setPrincipal]=useState(5000);const [rate,setRate]=useState(settings.defaultRate);const [weeks,setWeeks]=useState(settings.defaultWeeks);const [mode,setMode]=useState<'total'|'balance'>('total');const [firstDue,setFirstDue]=useState(()=>{const d=new Date();d.setDate(d.getDate()+7);return d.toISOString().slice(0,10)});const [feeType,setFeeType]=useState<'fixed'|'percent'>(settings.feeType);const [feeValue,setFeeValue]=useState(settings.feeValue);const [lateInterest,setLateInterest]=useState(settings.lateInterest);
  const client=clients.find(item=>item.id===clientId)!;const preview=useMemo(()=>generateInstallments({principal,rate,interestMode:mode,weeks,firstDueDate:firstDue}),[principal,rate,mode,weeks,firstDue]);const total=preview.reduce((sum,item)=>sum+item.amount,0);const risk=client?riskFor(client,loans,principal):null;
  const next=()=>setStep(value=>Math.min(2,value+1));const submit=(event:FormEvent)=>{event.preventDefault();if(step<2){next();return;}const id=uid('emp');onSave({id,clientId,contractNumber:`LE-${new Date().getFullYear()}-${id.slice(-4).toUpperCase()}`,principal,rate,interestMode:mode,weeks,firstDueDate:firstDue,feeType,feeValue,lateInterest,status:'Ativo',installments:preview,createdAt:new Date().toISOString().slice(0,10)});};
  return <><PageHeader eyebrow="NOVA OPERAÇÃO" title="Novo empréstimo" subtitle="Simule as condições, revise o risco e gere o contrato."/><Stepper steps={['Cliente e valor','Condições','Parcelas e aprovação']} active={step}/><form className="form-card loan-form" onSubmit={submit}>{step===0&&<><div className="form-section-title"><span>1</span><div><h3>Cliente e valor solicitado</h3><p>Selecione o cliente para calcular a análise de risco.</p></div></div><div className="form-grid"><label className="span-2">Cliente<select value={clientId} onChange={e=>setClientId(e.target.value)}>{clients.map(item=><option value={item.id} key={item.id}>{item.name} — {item.cpf}</option>)}</select></label><label>Valor principal<MoneyInput value={principal} onChange={setPrincipal} required/></label><label>Primeiro vencimento<input type="date" value={firstDue} onChange={e=>setFirstDue(e.target.value)} required/></label></div>{risk&&<div className={`risk-preview ${risk.level==='Baixo risco'?'low':risk.level==='Médio risco'?'medium':'high'}`}><RiskBadge level={risk.level} score={risk.score}/><div><b>Análise para {client.name}</b><p>{risk.reasons.join(' • ')}</p></div></div>}</>}{step===1&&<><div className="form-section-title"><span>2</span><div><h3>Condições financeiras</h3><p>Defina juros, prazo e regras de atraso.</p></div></div><div className="form-grid"><label>Taxa de juros (%)<input type="number" min="0" step="0.01" value={rate} onChange={e=>setRate(Number(e.target.value))}/></label><label>Prazo em semanas<input type="number" min="1" max="104" value={weeks} onChange={e=>setWeeks(Number(e.target.value))}/></label><label className="span-2">Modalidade de juros<div className="choice-cards"><button type="button" className={mode==='total'?'active':''} onClick={()=>setMode('total')}><b>Fixo sobre o total</b><small>Parcelas iguais e previsíveis</small></button><button type="button" className={mode==='balance'?'active':''} onClick={()=>setMode('balance')}><b>Sobre saldo devedor</b><small>Juros diminuem com o saldo</small></button></div></label><label>Tipo de multa<select value={feeType} onChange={e=>setFeeType(e.target.value as 'fixed'|'percent')}><option value="percent">Percentual</option><option value="fixed">Valor fixo</option></select></label><label>{feeType==='percent'?'Multa (%)':'Multa fixa'}<input type="number" min="0" step="0.01" value={feeValue} onChange={e=>setFeeValue(Number(e.target.value))}/></label><label>Juros de mora ao dia (%)<input type="number" min="0" step="0.001" value={lateInterest} onChange={e=>setLateInterest(Number(e.target.value))}/></label></div></>}{step===2&&<><div className="simulation-summary"><span><small>Valor principal</small><b>{currency(principal)}</b></span><span><small>Total de juros</small><b>{currency(total-principal)}</b></span><span><small>Total do contrato</small><b>{currency(total)}</b></span><span><small>Parcela inicial</small><b>{currency(preview[0]?.amount||0)}</b></span></div><div className="table-scroll"><div className="installment-table"><div className="table-row table-head"><span>#</span><span>Vencimento</span><span>Principal</span><span>Juros</span><span>Parcela</span></div>{preview.map(item=><div className="table-row" key={item.id}><span>{String(item.number).padStart(2,'0')}</span><span>{shortDate(item.dueDate)}</span><span>{currency(item.principal)}</span><span>{currency(item.interest)}</span><strong>{currency(item.amount)}</strong></div>)}</div></div><div className="approval-note"><span>✓</span><div><b>Pronto para aprovação manual</b><p>Ao confirmar, o sistema criará o contrato e todas as parcelas. O score é apenas uma recomendação.</p></div></div></>}<div className="form-actions"><button type="button" className="secondary-button" onClick={step?()=>setStep(value=>value-1):onCancel}>{step?'Voltar':'Cancelar'}</button><button className="primary-button">{step===2?'Aprovar e criar contrato':'Continuar →'}</button></div></form></>;
}

function LoanDetail({ loan, client, onContract, onRenegotiate, onConfirm }: {loan:Loan;client:Client;onContract:()=>void;onRenegotiate:()=>void;onConfirm:(id:string)=>void}) {
  const paid=loan.installments.filter(item=>item.status==='Pago');const progress=paid.length/loan.installments.length*100;const late=loan.installments.filter(item=>item.status==='Atrasado');
  return <><PageHeader eyebrow={loan.contractNumber} title={`Empréstimo de ${client.name}`} subtitle={`Criado em ${shortDate(loan.createdAt)} • ${loan.interestMode==='total'?'Juros fixos sobre o total':'Juros sobre saldo devedor'}`} action={<><button className="secondary-button" onClick={onContract}>▤ Contrato</button>{loan.status==='Ativo'&&<button className="primary-button" onClick={onRenegotiate}>Renegociar</button>}</>}/><section className="loan-overview"><div className="loan-main-card"><p className="eyebrow">SALDO DEVEDOR</p><h3>{currency(loanBalance(loan))}</h3><div className="progress large"><span style={{width:`${progress}%`}}/></div><p>{paid.length} de {loan.installments.length} parcelas pagas • {Math.round(progress)}% concluído</p></div><div className="loan-stat"><small>Valor emprestado</small><b>{currency(loan.principal)}</b></div><div className="loan-stat"><small>Total do contrato</small><b>{currency(loan.installments.reduce((sum,item)=>sum+item.amount,0))}</b></div><div className="loan-stat"><small>Taxa e prazo</small><b>{loan.rate}% • {loan.weeks} sem.</b></div><div className="loan-stat"><small>Situação</small><StatusBadge status={loan.status}/></div></section>{late.length>0&&<div className="alert-banner danger"><span>!</span><div><b>{late.length} parcela(s) em atraso</b><p>O saldo exibido já considera multa e juros de mora até hoje.</p></div></div>}{loan.originalLoanId&&<div className="alert-banner info"><span>↻</span><div><b>Contrato renegociado</b><p>Este contrato substitui o saldo do contrato {loan.originalLoanId} e mantém a rastreabilidade.</p></div></div>}<section className="table-card"><div className="section-title"><div><p className="eyebrow">CRONOGRAMA</p><h3>Tabela de parcelas</h3></div><span>{loan.installments.length} semanas</span></div><div className="table-scroll"><div className="installment-table detail"><div className="table-row table-head"><span>Parcela</span><span>Vencimento</span><span>Valor</span><span>Encargos</span><span>Status</span><span></span></div>{loan.installments.map(item=>{const due=payableAmount(loan,item);return <div className="table-row" key={item.id}><span><b>#{String(item.number).padStart(2,'0')}</b></span><span><b>{shortDate(item.dueDate)}</b>{daysLate(item.dueDate)>0&&item.status!=='Pago'&&<small>{daysLate(item.dueDate)} dias de atraso</small>}</span><span><b>{currency(item.amount)}</b><small>Principal {currency(item.principal)}</small></span><span>{due>item.amount?<b className="red-text">+ {currency(due-item.amount)}</b>:'—'}</span><StatusBadge status={item.status}/><span>{item.status==='Aguardando'&&<button className="outline-button small" onClick={()=>onConfirm(item.id)}>Confirmar</button>}{item.receiptName&&<small className="receipt">▤ {item.receiptName}</small>}</span></div>})}</div></div></section></>;
}

function PaymentsView({ loans, clients, onConfirm, onReject, onOpenLoan }: {loans:Loan[];clients:Client[];onConfirm:(loanId:string,id:string)=>void;onReject:(loanId:string,id:string)=>void;onOpenLoan:(id:string)=>void}) {
  const [tab,setTab]=useState<'awaiting'|'late'|'all'>('awaiting');const rows=loans.flatMap(loan=>loan.installments.map(item=>({loan,item,client:clients.find(c=>c.id===loan.clientId)!}))).filter(row=>tab==='awaiting'?row.item.status==='Aguardando':tab==='late'?row.item.status==='Atrasado':row.item.status!=='Pago');
  return <><PageHeader eyebrow="CONFERÊNCIA" title="Pagamentos" subtitle="Revise comprovantes e acompanhe cobranças pendentes."/><div className="tabs"><button className={tab==='awaiting'?'active':''} onClick={()=>setTab('awaiting')}>Aguardando confirmação <em>{loans.flatMap(l=>l.installments).filter(i=>i.status==='Aguardando').length}</em></button><button className={tab==='late'?'active':''} onClick={()=>setTab('late')}>Em atraso</button><button className={tab==='all'?'active':''} onClick={()=>setTab('all')}>Todos pendentes</button></div>{rows.length?<section className="payment-cards">{rows.map(({loan,item,client})=><article key={item.id}><div className="payment-person"><span className="avatar light">{initials(client.name)}</span><span><b>{client.name}</b><small>{loan.contractNumber} • Parcela {item.number}/{loan.weeks}</small></span><StatusBadge status={item.status}/></div><div className="payment-amount"><small>{item.status==='Atrasado'?'Total atualizado':'Valor informado'}</small><b>{currency(payableAmount(loan,item))}</b><span>Vencimento {shortDate(item.dueDate)}</span></div>{item.receiptName?<button className="receipt-preview"><span>▤</span><span><b>Comprovante anexado</b><small>{item.receiptName}</small></span><em>Visualizar</em></button>:<div className="no-receipt">Nenhum comprovante anexado</div>}<div className="card-actions"><button className="text-button" onClick={()=>onOpenLoan(loan.id)}>Ver contrato</button>{item.status==='Aguardando'&&<><button className="danger-link" onClick={()=>onReject(loan.id,item.id)}>Recusar</button><button className="primary-button" onClick={()=>onConfirm(loan.id,item.id)}>✓ Confirmar recebimento</button></>}</div></article>)}</section>:<EmptyState title={tab==='awaiting'?'Tudo conferido':'Nenhuma parcela nesta situação'} text={tab==='awaiting'?'Não há pagamentos aguardando confirmação.':'Os filtros não retornaram cobranças.'}/>}</>;
}

function DashboardView({ clients, loans }: {clients:Client[];loans:Loan[]}) {
  const [period,setPeriod]=useState('6 meses');const rows=loans.flatMap(loan=>loan.installments.map(item=>({loan,item})));const received=rows.filter(r=>r.item.status==='Pago').reduce((s,r)=>s+r.item.paidAmount,0);const principalPaid=rows.filter(r=>r.item.status==='Pago').reduce((s,r)=>s+r.item.principal,0);const late=rows.filter(r=>r.item.status==='Atrasado');const pending=rows.filter(r=>r.item.status!=='Pago');const defaultRate=pending.length?late.length/pending.length*100:0;const ranking=clients.map(client=>{const its=rows.filter(r=>r.loan.clientId===client.id);const paid=its.filter(r=>r.item.status==='Pago').length;const delayed=its.filter(r=>r.item.status==='Atrasado').length;return {client,score:paid*8-delayed*15,paid,delayed}}).sort((a,b)=>b.score-a.score);
  const forecast=[{m:'Mar',p:8300,r:6900},{m:'Abr',p:9100,r:8750},{m:'Mai',p:7800,r:7200},{m:'Jun',p:10200,r:9800},{m:'Jul',p:11400,r:10100},{m:'Ago',p:12600,r:9200}];const max=Math.max(...forecast.map(i=>i.p));
  return <><PageHeader eyebrow="INTELIGÊNCIA FINANCEIRA" title="Dashboard" subtitle="Acompanhe rentabilidade, caixa e risco da carteira." action={<select value={period} onChange={e=>setPeriod(e.target.value)}><option>Últimos 30 dias</option><option>6 meses</option><option>Este ano</option></select>}/><section className="summary-grid"><SummaryCard label="Carteira ativa" value={currency(loans.reduce((s,l)=>s+loanBalance(l),0))} detail="Capital e juros em aberto"/><SummaryCard label="Receita de juros" value={currency(received-principalPaid)} detail="Em pagamentos confirmados" tone="green"/><SummaryCard label="Inadimplência" value={`${defaultRate.toFixed(1).replace('.',',')}%`} detail={`${late.length} parcelas atrasadas`} tone={defaultRate>10?'red':'gold'}/><SummaryCard label="Ticket médio" value={currency(loans.reduce((s,l)=>s+l.principal,0)/Math.max(1,loans.length))} detail="Por empréstimo" tone="gold"/></section><div className="analytics-grid"><section className="panel wide-chart"><div className="panel-head"><div><p className="eyebrow">CAIXA • {period.toUpperCase()}</p><h3>Previsto x realizado</h3></div><div className="chart-legend"><span><i className="planned"/>Previsto</span><span><i className="received"/>Realizado</span></div></div><div className="value-chart">{forecast.map(item=><div key={item.m}><div className="value-bars"><span style={{height:`${item.p/max*100}%`}} title={currency(item.p)}/><span style={{height:`${item.r/max*100}%`}} title={currency(item.r)}/></div><small>{item.m}</small></div>)}</div></section><section className="panel donut-panel"><div><p className="eyebrow">COMPOSIÇÃO</p><h3>Status das parcelas</h3></div><div className="donut" style={{background:`conic-gradient(#24734b 0 ${rows.filter(r=>r.item.status==='Pago').length/Math.max(1,rows.length)*100}%,#c7a135 0 ${(rows.filter(r=>r.item.status==='Pago').length+rows.filter(r=>r.item.status==='Pendente').length)/Math.max(1,rows.length)*100}%,#b74843 0)`}}><span><b>{rows.length}</b><small>parcelas</small></span></div><div className="donut-legend"><span><i className="green"/>Pagas <b>{rows.filter(r=>r.item.status==='Pago').length}</b></span><span><i className="gold"/>Pendentes <b>{rows.filter(r=>r.item.status==='Pendente').length}</b></span><span><i className="red"/>Atrasadas <b>{late.length}</b></span></div></section></div><div className="detail-grid"><section className="panel"><div className="panel-head"><h3>Ranking de clientes</h3><small>Melhores pagadores</small></div><div className="ranking-list">{ranking.map((entry,index)=><div key={entry.client.id}><em>{index+1}</em><span className="avatar light">{initials(entry.client.name)}</span><span><b>{entry.client.name}</b><small>{entry.paid} pagas • {entry.delayed} atrasadas</small></span><RiskBadge level={riskFor(entry.client,loans).level} compact/></div>)}</div></section><section className="panel"><div className="panel-head"><h3>Valores em atraso</h3><small>{late.length} ocorrências</small></div><div className="late-list">{late.slice(0,5).map(({loan,item})=>{const client=clients.find(c=>c.id===loan.clientId)!;return <div key={item.id}><span><b>{client.name}</b><small>{daysLate(item.dueDate)} dias • Parcela {item.number}</small></span><b>{currency(payableAmount(loan,item))}</b></div>})}</div></section></div></>;
}

function TeamView({team,setTeam,onNew,notify}:{team:TeamMember[];setTeam:React.Dispatch<React.SetStateAction<TeamMember[]>>;onNew:()=>void;notify:(message:string)=>void}) {
  const permissions=['Cadastrar clientes','Criar empréstimos','Registrar pagamentos','Acessar relatórios'];
  const togglePermission=(id:string,permission:string)=>setTeam(items=>items.map(member=>member.id===id?{...member,permissions:member.permissions.includes(permission)?member.permissions.filter(p=>p!==permission):[...member.permissions,permission]}:member));
  return <><PageHeader eyebrow="ACESSO E SEGURANÇA" title="Equipe" subtitle="Controle quem pode acessar cada parte da operação." action={<button className="primary-button" onClick={onNew}>＋ Adicionar membro</button>}/><div className="alert-banner info"><span>i</span><div><b>Permissões por função</b><p>Membros da equipe não veem o dashboard financeiro geral sem permissão explícita.</p></div></div><section className="team-list">{team.map(member=><article key={member.id}><div className="team-head"><span className="avatar">{initials(member.name)}</span><span><b>{member.name}</b><small>{member.email}</small></span><label className="switch"><input type="checkbox" checked={member.active} onChange={()=>{setTeam(items=>items.map(item=>item.id===member.id?{...item,active:!item.active}:item));notify('Acesso da equipe atualizado.')}}/><span/></label></div><div className="permission-grid">{permissions.map(permission=><label key={permission}><input type="checkbox" checked={member.permissions.includes(permission)} onChange={()=>togglePermission(member.id,permission)}/><span>✓</span>{permission}</label>)}</div></article>)}</section></>;
}

function SettingsView({value,onSave}:{value:AppSettings;onSave:(value:AppSettings)=>void}) {
  const [form,setForm]=useState(value);const update=<K extends keyof AppSettings>(key:K,newValue:AppSettings[K])=>setForm(state=>({...state,[key]:newValue}));
  return <><PageHeader eyebrow="PREFERÊNCIAS" title="Configurações" subtitle="Dados da empresa, recebimento e regras padrão."/><form className="settings-layout" onSubmit={event=>{event.preventDefault();onSave(form)}}><section className="form-card"><div className="form-section-title"><span>1</span><div><h3>Dados da empresa</h3><p>Informações exibidas nos contratos e no acesso do cliente.</p></div></div><div className="form-grid"><label>Nome da empresa<input value={form.companyName} onChange={e=>update('companyName',e.target.value)}/></label><label>CPF/CNPJ<input value={form.document} onChange={e=>update('document',e.target.value)}/></label><label>Telefone<input value={form.phone} onChange={e=>update('phone',e.target.value)}/></label><label>Chave PIX<input value={form.pixKey} onChange={e=>update('pixKey',e.target.value)}/></label></div></section><section className="form-card"><div className="form-section-title"><span>2</span><div><h3>Regras financeiras padrão</h3><p>Valores sugeridos ao criar novos empréstimos.</p></div></div><div className="form-grid"><label>Juros padrão (%)<input type="number" step=".01" value={form.defaultRate} onChange={e=>update('defaultRate',Number(e.target.value))}/></label><label>Prazo padrão (semanas)<input type="number" value={form.defaultWeeks} onChange={e=>update('defaultWeeks',Number(e.target.value))}/></label><label>Tipo de multa<select value={form.feeType} onChange={e=>update('feeType',e.target.value as 'fixed'|'percent')}><option value="percent">Percentual</option><option value="fixed">Fixa</option></select></label><label>Valor da multa<input type="number" step=".01" value={form.feeValue} onChange={e=>update('feeValue',Number(e.target.value))}/></label><label>Mora ao dia (%)<input type="number" step=".001" value={form.lateInterest} onChange={e=>update('lateInterest',Number(e.target.value))}/></label><label>Lembrete antes do vencimento (dias)<input type="number" value={form.reminderDays} onChange={e=>update('reminderDays',Number(e.target.value))}/></label></div></section><div className="settings-save"><p>As alterações valem para novos contratos. Os contratos atuais mantêm suas próprias regras.</p><button className="primary-button">Salvar configurações</button></div></form></>;
}

function ClientHome({client,loans,settings,onPayment}:{client:Client;loans:Loan[];settings:AppSettings;onPayment:(loanId:string,id:string)=>void}) {
  const clientLoans=loans.filter(loan=>loan.clientId===client.id&&loan.status==='Ativo');const loan=clientLoans[0];if(!loan)return <><PageHeader eyebrow="ÁREA DO CLIENTE" title={`Olá, ${client.name.split(' ')[0]}`} subtitle="Acompanhe seus contratos e pagamentos."/><EmptyState title="Nenhum empréstimo ativo" text="Você não possui cobranças em aberto neste momento."/></>;
  const next=loan.installments.find(item=>item.status!=='Pago');const paid=loan.installments.filter(item=>item.status==='Pago').length;
  return <><section className="client-welcome"><div><p className="eyebrow">ÁREA DO CLIENTE</p><h2>Olá, {client.name.split(' ')[0]}.</h2><p>Acompanhe seu saldo e mantenha seus pagamentos em dia.</p></div><StatusBadge status={loan.status}/></section><section className="client-balance"><div><small>Seu saldo devedor</small><strong>{currency(loanBalance(loan))}</strong><p>Contrato {loan.contractNumber}</p></div><div className="client-progress"><span><b>{paid}</b><small>pagas</small></span><div><div className="progress large"><span style={{width:`${paid/loan.installments.length*100}%`}}/></div><p>{paid} de {loan.installments.length} parcelas concluídas</p></div></div></section>{next&&<section className={`next-payment ${next.status==='Atrasado'?'late':''}`}><div className="next-date"><span>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit'}).format(new Date(`${next.dueDate}T12:00:00`))}</span><b>{new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(`${next.dueDate}T12:00:00`)).replace('.','').toUpperCase()}</b></div><div><p className="eyebrow">{next.status==='Atrasado'?'PAGAMENTO EM ATRASO':'PRÓXIMA PARCELA'}</p><h3>{currency(payableAmount(loan,next))}</h3><p>Parcela {next.number} de {loan.installments.length} • Vence em {shortDate(next.dueDate)}</p></div><div><StatusBadge status={next.status}/>{next.status!=='Aguardando'&&<button className="primary-button" onClick={()=>onPayment(loan.id,next.id)}>Pagar com PIX</button>}</div></section>}<div className="client-layout"><section className="panel"><div className="panel-head"><div><p className="eyebrow">HISTÓRICO</p><h3>Minhas parcelas</h3></div></div><div className="client-installments">{loan.installments.map(item=><div key={item.id}><span className={`installment-number ${item.status.toLowerCase()}`}>{item.status==='Pago'?'✓':item.number}</span><span><b>Parcela {item.number}</b><small>{shortDate(item.dueDate)}</small></span><b>{currency(payableAmount(loan,item))}</b><StatusBadge status={item.status}/></div>)}</div></section><aside className="panel support-card"><span>?</span><h3>Precisa de ajuda?</h3><p>Fale com {settings.companyName} sobre seu contrato ou pagamento.</p><button className="outline-button">{settings.phone}</button><button className="text-button">Baixar contrato</button></aside></div></>;
}

function ContractModal({loan,client,settings,onClose}:{loan:Loan;client:Client;settings:AppSettings;onClose:()=>void}) {
  return <Modal title="Contrato digital" onClose={onClose} wide><div className="contract-toolbar"><span>Documento {loan.contractNumber}</span><button className="secondary-button" onClick={()=>window.print()}>Imprimir / salvar PDF</button></div><article className="contract-print"><header><div className="contract-logo"><span>L</span>Lucas <b>EMPRED</b></div><div><b>{loan.contractNumber}</b><small>Gerado em {shortDate(loan.createdAt)}</small></div></header><h1>CONTRATO PARTICULAR DE EMPRÉSTIMO</h1><p>Pelo presente instrumento, de um lado <b>{settings.companyName}</b>, inscrito sob {settings.document}, doravante CREDOR, e de outro <b>{client.name}</b>, CPF {client.cpf}, RG {client.rg}, residente em {client.address}, doravante DEVEDOR, acordam as condições abaixo.</p><h2>1. DO OBJETO E CONDIÇÕES</h2><p>O CREDOR entrega ao DEVEDOR a quantia de <b>{currency(loan.principal)}</b>. O valor será restituído em <b>{loan.weeks} parcelas semanais</b>, com taxa contratual de <b>{loan.rate}%</b>, na modalidade {loan.interestMode==='total'?'fixa sobre o valor total':'sobre o saldo devedor'}.</p><div className="contract-values"><span><small>Principal</small><b>{currency(loan.principal)}</b></span><span><small>Total previsto</small><b>{currency(loan.installments.reduce((s,i)=>s+i.amount,0))}</b></span><span><small>1º vencimento</small><b>{shortDate(loan.firstDueDate)}</b></span></div><h2>2. DO ATRASO</h2><p>Em caso de atraso, incidirá multa {loan.feeType==='fixed'?`fixa de ${currency(loan.feeValue)}`:`de ${loan.feeValue}%`} por parcela, além de juros de mora de {loan.lateInterest}% ao dia.</p><h2>3. DOS PAGAMENTOS</h2><p>Os pagamentos serão realizados por PIX para a chave {settings.pixKey}, sujeitos à confirmação do CREDOR. O histórico mantido no sistema integra este contrato.</p><h2>4. DA CIÊNCIA</h2><p>As partes declaram compreender e aceitar as condições financeiras, o cronograma e as regras de renegociação vinculada ao saldo devedor.</p><div className="contract-signatures"><div>{client.signature?<img src={client.signature} alt="Assinatura do cliente"/>:<span/>}<b>{client.name}</b><small>Devedor</small></div><div><span className="admin-signature">Lucas EMPRED</span><b>{settings.companyName}</b><small>Credor</small></div></div></article></Modal>;
}

function RenegotiateModal({loan,settings,onSave,onClose}:{loan:Loan;settings:AppSettings;onSave:(loan:Loan)=>void;onClose:()=>void}) {
  const balance=loanBalance(loan);const [rate,setRate]=useState(settings.defaultRate);const [weeks,setWeeks]=useState(settings.defaultWeeks);const [firstDue,setFirstDue]=useState(()=>{const d=new Date();d.setDate(d.getDate()+7);return d.toISOString().slice(0,10)});const preview=generateInstallments({principal:balance,rate,interestMode:'total',weeks,firstDueDate:firstDue});
  return <Modal title="Renegociar empréstimo" onClose={onClose}><form onSubmit={event=>{event.preventDefault();const id=uid('ren');onSave({id,clientId:loan.clientId,contractNumber:`LE-R-${id.slice(-4).toUpperCase()}`,principal:balance,rate,interestMode:'total',weeks,firstDueDate:firstDue,feeType:loan.feeType,feeValue:loan.feeValue,lateInterest:loan.lateInterest,status:'Ativo',installments:preview,createdAt:new Date().toISOString().slice(0,10),originalLoanId:loan.id})}}><div className="renegotiation-balance"><small>Saldo consolidado com encargos</small><b>{currency(balance)}</b><span>Contrato original: {loan.contractNumber}</span></div><div className="form-grid"><label>Nova taxa (%)<input type="number" step=".01" value={rate} onChange={e=>setRate(Number(e.target.value))}/></label><label>Novo prazo (semanas)<input type="number" min="1" value={weeks} onChange={e=>setWeeks(Number(e.target.value))}/></label><label className="span-2">Primeiro vencimento<input type="date" value={firstDue} onChange={e=>setFirstDue(e.target.value)}/></label></div><div className="simulation-mini"><span><small>Nova parcela</small><b>{currency(preview[0]?.amount||0)}</b></span><span><small>Novo total</small><b>{currency(preview.reduce((s,i)=>s+i.amount,0))}</b></span></div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button className="primary-button">Criar renegociação</button></div></form></Modal>;
}

function PaymentModal({loan,installment,settings,onSave,onClose}:{loan:Loan;installment:Installment;settings:AppSettings;onSave:(receipt?:string)=>void;onClose:()=>void}) {
  const [receipt,setReceipt]=useState('');
  return <Modal title="Pagar parcela com PIX" onClose={onClose}><div className="pix-payment"><div className="fake-qr" aria-label="QR code PIX ilustrativo"><span/></div><div><p className="eyebrow">VALOR ATUALIZADO</p><h3>{currency(payableAmount(loan,installment))}</h3><p>Parcela {installment.number} • {shortDate(installment.dueDate)}</p></div></div><label className="copy-field">Chave PIX<div><input readOnly value={settings.pixKey}/><button type="button" onClick={()=>navigator.clipboard?.writeText(settings.pixKey)}>Copiar</button></div></label><label className="upload-zone compact"><input type="file" accept="image/*,.pdf" onChange={event=>setReceipt(event.target.files?.[0]?.name||'')}/><span>↑</span><b>{receipt||'Anexar comprovante (opcional)'}</b></label><p className="modal-description">Depois de pagar, marque como enviado. A parcela ficará aguardando a confirmação do administrador.</p><div className="modal-actions"><button className="secondary-button" onClick={onClose}>Cancelar</button><button className="primary-button" onClick={()=>onSave(receipt)}>Marcar como pago</button></div></Modal>;
}

function TeamModal({onSave,onClose}:{onSave:(member:TeamMember)=>void;onClose:()=>void}) {
  const [name,setName]=useState('');const [email,setEmail]=useState('');
  return <Modal title="Adicionar membro" onClose={onClose}><form onSubmit={event=>{event.preventDefault();onSave({id:uid('team'),name,email,active:true,permissions:['Cadastrar clientes']})}}><div className="form-grid one"><label>Nome completo<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>E-mail<input required type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label></div><p className="modal-description">O convite será simulado nesta fase. Você poderá definir as permissões após salvar.</p><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button className="primary-button">Adicionar membro</button></div></form></Modal>;
}

function Notifications({loans,clients,onClose,onOpen}:{loans:Loan[];clients:Client[];onClose:()=>void;onOpen:(id:string)=>void}) {
  const notifications=loans.flatMap(loan=>loan.installments.filter(item=>item.status==='Aguardando'||item.status==='Atrasado').map(item=>({loan,item,client:clients.find(c=>c.id===loan.clientId)!}))).slice(0,6);
  return <section className="notifications-popover"><header><div><h3>Notificações</h3><small>{notifications.length} itens precisam de atenção</small></div><button onClick={onClose}>×</button></header><div>{notifications.map(({loan,item,client})=><button key={item.id} onClick={()=>onOpen(loan.id)}><span className={`notification-icon ${item.status==='Atrasado'?'late':'waiting'}`}>{item.status==='Atrasado'?'!':'✓'}</span><span><b>{item.status==='Atrasado'?'Parcela em atraso':'Pagamento enviado'}</b><small>{client.name} • Parcela {item.number} • {currency(payableAmount(loan,item))}</small></span><em>›</em></button>)}</div>{!notifications.length&&<p className="popover-empty">Tudo em dia por aqui.</p>}</section>;
}
